// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        depositAmount = bound(depositAmount, c.MinDeposit(), type(uint96).max);
        address actor = address(0xBEEF);
        vm.deal(actor, depositAmount);

        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        cashOutAmount = bound(cashOutAmount, 1, c.balances(actor));

        vm.prank(actor);
        c.CashOut(cashOutAmount);

        assertTrue(c.balances(actor) == depositAmount - cashOutAmount);
    }
}
